select
a.warn_id,
a.warn_level,
a.warn_time,
a.warn_type,
a.device_id,
a.cunstom_id,
a.instance_id,
a.std_mete_id,
a.conf_mode,
a.conf_time,
a.conf_user_id,
a.conf_info,
a.if_warn_disable,
a.alarm_source,
a.warn_subtype,
a.device_code,
a.image_path,
a.video_path,
a.value,
a.defect,
a.defect_level,
a.out_range,
a.link_message
from t_warn_info a
where 1 = 1
 and a.warn_id = #{warnId, jdbcType=BIGINT}
 and a.warn_level = #{warnLevel, jdbcType=INTEGER}
 and a.warn_time = #{warnTime, jdbcType=TIMESTAMP}
 and a.warn_type = #{warnType, jdbcType=INTEGER}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.cunstom_id = #{cunstomId, jdbcType=VARCHAR}
 and a.instance_id = #{instanceId, jdbcType=BIGINT}
 and a.std_mete_id = #{stdMeteId, jdbcType=BIGINT}
 and a.conf_mode = #{confMode, jdbcType=INTEGER}
 and a.conf_time = #{confTime, jdbcType=TIMESTAMP}
 and a.conf_user_id = #{confUserId, jdbcType=VARCHAR}
 and a.conf_info = #{confInfo, jdbcType=VARCHAR}
 and a.if_warn_disable = #{ifWarnDisable, jdbcType=INTEGER}
 and a.alarm_source = #{alarmSource, jdbcType=INTEGER}
 and a.warn_subtype = #{warnSubtype, jdbcType=INTEGER}
 and a.device_code = #{deviceCode, jdbcType=VARCHAR}
 and a.image_path = #{imagePath, jdbcType=VARCHAR}
 and a.video_path = #{videoPath, jdbcType=VARCHAR}
 and a.value = #{value, jdbcType=VARCHAR}
 and a.defect = #{defect, jdbcType=INTEGER}
 and a.defect_level = #{defectLevel, jdbcType=INTEGER}
 and a.out_range = #{outRange, jdbcType=VARCHAR}
 and a.link_message = #{linkMessage, jdbcType=VARCHAR}

select
a.warn_id,
a.warn_level,
a.warn_time,
a.warn_type,
a.device_id,
a.cunstom_id,
a.instance_id,
a.std_mete_id,
a.conf_mode,
a.conf_time,
a.conf_user_id,
a.conf_info,
a.if_warn_disable,
a.alarm_source,
a.warn_subtype,
a.device_code,
a.image_path,
a.video_path,
a.value,
a.defect,
a.defect_level,
a.out_range,
a.link_message
from t_warn_info a
where 1 = 1
 and a.warn_id = #{warnId, jdbcType=BIGINT}
 and a.warn_level = #{warnLevel, jdbcType=INTEGER}
 and a.warn_time = #{warnTime, jdbcType=TIMESTAMP}
 and a.warn_type = #{warnType, jdbcType=INTEGER}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.cunstom_id = #{cunstomId, jdbcType=VARCHAR}
 and a.instance_id = #{instanceId, jdbcType=BIGINT}
 and a.std_mete_id = #{stdMeteId, jdbcType=BIGINT}
 and a.conf_mode = #{confMode, jdbcType=INTEGER}
 and a.conf_time = #{confTime, jdbcType=TIMESTAMP}
 and a.conf_user_id = #{confUserId, jdbcType=VARCHAR}
 and a.conf_info = #{confInfo, jdbcType=VARCHAR}
 and a.if_warn_disable = #{ifWarnDisable, jdbcType=INTEGER}
 and a.alarm_source = #{alarmSource, jdbcType=INTEGER}
 and a.warn_subtype = #{warnSubtype, jdbcType=INTEGER}
 and a.device_code = #{deviceCode, jdbcType=VARCHAR}
 and a.image_path = #{imagePath, jdbcType=VARCHAR}
 and a.video_path = #{videoPath, jdbcType=VARCHAR}
 and a.value = #{value, jdbcType=VARCHAR}
 and a.defect = #{defect, jdbcType=INTEGER}
 and a.defect_level = #{defectLevel, jdbcType=INTEGER}
 and a.out_range = #{outRange, jdbcType=VARCHAR}
 and a.link_message = #{linkMessage, jdbcType=VARCHAR}

SELECT
DATE_FORMAT( warn_time, '%Y-%m-%d' ) day1,
count(*) count
FROM
( SELECT * FROM (select
a.warn_time
from t_warn_info a, t_std_device b
where 1=1
 and a.warn_level = #{warnLevel, jdbcType=INTEGER}
 and a.conf_mode = #{confMode, jdbcType=INTEGER}
 and a.alarm_source = #{alarmSource, jdbcType=INTEGER}
 and a.value like concat("%",#{value, jdbcType=INTEGER},"%")
 and a.device_id in (select device_id from t_std_device where device_name like concat("%",#{deviceName, jdbcType=VARCHAR},"%"))
 and a.warn_time BETWEEN #{startTime, jdbcType=TIMESTAMP} AND #{endTime, jdbcType=TIMESTAMP}
and a.device_id = b.device_id
union all(
select
b.alarm_time
from robot_alarm b
where 1=1
 and b.alarm_level = #{warnLevel, jdbcType=INTEGER}
 and b.alarm_state = #{confMode, jdbcType=INTEGER}
 and b.alarm_info like concat("%",#{value, jdbcType=INTEGER},"%")
 and b.alarm_time BETWEEN #{startTime, jdbcType=TIMESTAMP} AND #{endTime, jdbcType=TIMESTAMP}
)) time
WHERE period_diff(date_format(now( ),'%y%m'),date_format(warn_time,'%y%m'))=0 ) as robot
GROUP BY
day1;
